import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";

export const fps = 25;
export const durationInFrames = 220;

const COLORS = {
  sky: "#1a0a2e",
  skyMid: "#3d1a5c",
  lava: "#FF4500",
  lavaGlow: "#FF8C00",
  lavaHot: "#FFD700",
  smoke: "rgba(80,60,80,0.5)",
  rock: "#2a1a0a",
  rockMid: "#3d2a1a",
  rockDark: "#1a0a00",
  ringGold: "#FFD700",
  ringInner: "#B8860B",
  manSkin: "#FDBCB4",
  manCloak: "#2a0a4a",
  manCloakLight: "#4a1a6a",
  accent: "#FF64B8",
  bg: "#12091A",
};

const TRANSITION = 15;

const BlackScreen: React.FC = () => (
  <AbsoluteFill style={{ backgroundColor: COLORS.bg }} />
);

// Lava particle
const LavaParticle: React.FC<{ x: number; baseDelay: number; size: number; speed: number }> = ({
  x, baseDelay, size, speed,
}) => {
  const frame = useCurrentFrame();
  const cycleLength = speed;
  const localFrame = (frame + baseDelay) % cycleLength;
  const riseProgress = localFrame / cycleLength;
  const y = interpolate(riseProgress, [0, 1], [0, -350]);
  const opacity = interpolate(riseProgress, [0, 0.4, 0.8, 1], [0, 0.9, 0.5, 0]);
  const scale = interpolate(riseProgress, [0, 0.5, 1], [0.5, 1.2, 0.3]);
  const wobble = Math.sin(localFrame * 0.3 + x) * 30;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        bottom: 0,
        width: size,
        height: size,
        borderRadius: "50%",
        background: `radial-gradient(circle, ${COLORS.lavaHot}, ${COLORS.lava})`,
        opacity,
        transform: `translate(${wobble}px, ${y}px) scale(${scale})`,
        boxShadow: `0 0 ${size * 2}px ${COLORS.lavaGlow}`,
        pointerEvents: "none",
      }}
    />
  );
};

// Smoke puff
const SmokePuff: React.FC<{ x: number; delay: number }> = ({ x, delay }) => {
  const frame = useCurrentFrame();
  const cycleLength = 90;
  const localFrame = (frame + delay) % cycleLength;
  const riseProgress = localFrame / cycleLength;
  const y = interpolate(riseProgress, [0, 1], [0, -500]);
  const opacity = interpolate(riseProgress, [0, 0.2, 0.7, 1], [0, 0.35, 0.15, 0]);
  const scale = interpolate(riseProgress, [0, 1], [0.3, 2.5]);
  const wobble = Math.sin(localFrame * 0.15 + x * 0.01) * 60;

  return (
    <div
      style={{
        position: "absolute",
        left: x,
        bottom: 60,
        width: 120,
        height: 120,
        borderRadius: "50%",
        backgroundColor: COLORS.smoke,
        opacity,
        transform: `translate(${wobble}px, ${y}px) scale(${scale})`,
        pointerEvents: "none",
        filter: "blur(8px)",
      }}
    />
  );
};

// The Ring SVG
const TheRing: React.FC<{ progress: number; hoverAmt: number; glowPulse: number }> = ({
  progress,
  hoverAmt,
  glowPulse,
}) => {
  const scale = interpolate(progress, [0, 1], [0, 1]);
  const rotation = interpolate(progress, [0, 1], [720, 0]);
  const opacity = progress;
  const glowSize = 20 + glowPulse * 30;

  return (
    <div
      style={{
        position: "absolute",
        top: hoverAmt,
        left: "50%",
        transform: `translateX(-50%) scale(${scale}) rotate(${rotation}deg)`,
        opacity,
        filter: `drop-shadow(0 0 ${glowSize}px ${COLORS.ringGold}) drop-shadow(0 0 ${glowSize * 2}px rgba(255,215,0,0.5))`,
      }}
    >
      <svg width="180" height="90" viewBox="0 0 180 90">
        {/* Outer ring */}
        <ellipse
          cx="90"
          cy="45"
          rx="80"
          ry="35"
          fill="none"
          stroke={COLORS.ringGold}
          strokeWidth="14"
        />
        {/* Inner ring highlight */}
        <ellipse
          cx="90"
          cy="45"
          rx="80"
          ry="35"
          fill="none"
          stroke={COLORS.lavaHot}
          strokeWidth="4"
          strokeDasharray="20 10"
          opacity="0.7"
        />
        {/* Inner cutout */}
        <ellipse
          cx="90"
          cy="45"
          rx="60"
          ry="22"
          fill="none"
          stroke={COLORS.ringInner}
          strokeWidth="5"
          opacity="0.5"
        />
        {/* Elvish-like inscription glow */}
        <ellipse
          cx="90"
          cy="45"
          rx="80"
          ry="35"
          fill="none"
          stroke={COLORS.lavaHot}
          strokeWidth="2"
          opacity="0.4"
          strokeDasharray="5 3"
        />
      </svg>
    </div>
  );
};

// The Man SVG
