        <ellipse cx="110" cy="460" rx="50" ry="12" fill="rgba(0,0,0,0.4)" />

        {/* === CLOAK/CAPE === */}
        <path
          d={`M90,${220 + bodyBob} Q60,320 50,420 Q80,410 110,415 Q140,410 170,420 Q160,320 130,${220 + bodyBob} Z`}
