          height="80"
          rx="8"
          fill={COLORS.manCloak}
          transform={`rotate(${-legSwing * 8} 99 ${370 + bodyBob})`}
        />
        {/* Left boot */}
        <ellipse
          cx={`${96 - legSwing * 4}`}
          cy="453"
          rx="16"
          ry="10"
          fill="#1a0a00"
        />

        {/* === RIGHT LEG === */}
        <rect
          x="110"
          y={`${370 + bodyBob}`}
          width="22"
          height="80"
          rx="8"
          fill={COLORS.manCloak}
          transform={`rotate(${legSwing * 8} 121 ${370 + bodyBob})`}
        />
        {/* Right boot */}
        <ellipse
          cx={`${124 + legSwing * 4}`}
          cy="453"
          rx="16"
          ry="10"
          fill="#1a0a00"
        />

        {/* === BODY === */}
        <rect
          x="82"
          y={`${200 + bodyBob}`}
          width="56"
          height="90"
          rx="18"
          fill={COLORS.manCloak}
        />
        {/* Belt */}
        <rect
          x="82"
