        />

        {/* === LEFT ARM (raised to hold ring) === */}
        <g transform={`rotate(${-(60 + armRaise * 35)} 88 ${220 + bodyBob})`}>
          <rect
            x="62"
            y={`${200 + bodyBob}`}
            width="26"
            height="70"
            rx="10"
            fill={COLORS.manCloak}
          />
          {/* Left hand */}
          <circle cx="75" cy={`${200 + bodyBob}`} r="14" fill={COLORS.manSkin} />
        </g>

        {/* === RIGHT ARM (slightly raised, dramatic pose) === */}
        <g transform={`rotate(${30 - armRaise * 15} 132 ${220 + bodyBob})`}>
          <rect
            x="132"
            y={`${200 + bodyBob}`}
            width="26"
            height="70"
            rx="10"
            fill={COLORS.manCloak}
          />
          {/* Right hand */}
          <circle cx="145" cy={`${270 + bodyBob}`} r="14" fill={COLORS.manSkin} />
        </g>

        {/* === NECK === */}
        <rect
          x="100"
          y={`${165 + bodyBob}`}
          width="20"
          height="36"
          rx="8"
          fill={COLORS.manSkin}
        />

        {/* === HEAD === */}
        <ellipse
          cx="110"
          cy={`${148 + bodyBob}`}
          rx="34"
          ry="38"
          fill={COLORS.manSkin}
        />
        {/* Hair */}
        <path
          d={`M78,${140 + bodyBob} Q80,${108 + bodyBob} 110,${112 + bodyBob} Q140,${108 + bodyBob} 142,${140 + bodyBob} Q130,${118 + bodyBob} 110,${120 + bodyBob} Q90,${118 + bodyBob} 78,${140 + bodyBob} Z`}
          fill="#1a0800"
