};

// Main volcano scene
const VolcanoScene: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Sky gradient progress
  const skyProgress = spring({ frame, fps, delay: 0, config: { damping: 200 } });

  // Volcano entrance
  const volcanoProgress = spring({ frame, fps, delay: 5, config: { damping: 200 } });

  // Man entrance
  const manProgress = spring({ frame, fps, delay: 35, config: { damping: 200 } });

  // Ring entrance
  const ringProgress = spring({ frame, fps, delay: 55, config: { damping: 200 } });

  // Arm raise (man raises ring dramatically)
  const armRaiseProgress = spring({ frame, fps, delay: 70, config: { damping: 200 } });
  const armRaise = interpolate(armRaiseProgress, [0, 1], [0, 1]);

  // Breathing animation
  const breathe = Math.sin(frame * 0.12) * 0.5 + 0.5;

  // Leg micro-sway
  const legSwing = Math.sin(frame * 0.08) * 0.3;

  // Ring hover up and down
  const ringHover = Math.sin(frame * 0.1) * 12;
  const ringBase = -420; // above man's head
  const ringY = ringBase + ringHover;

  // Lava glow pulse
  const glowPulse = Math.sin(frame * 0.15) * 0.5 + 0.5;

  // Lava heat shimmer for volcano
  const shimmer = Math.sin(frame * 0.2) * 3;

  // Ring inscription glow pulse
  const inscriptionGlow = Math.sin(frame * 0.18) * 0.5 + 0.5;

  // Eruption sparks timing
  const erupting = frame > 50;

  // Lava particles
  const lavaParticles = [
    { x: 1850, baseDelay: 0, size: 28, speed: 55 },
    { x: 1900, baseDelay: 12, size: 18, speed: 48 },
    { x: 1810, baseDelay: 22, size: 22, speed: 60 },
    { x: 1870, baseDelay: 35, size: 32, speed: 45 },
    { x: 1940, baseDelay: 8, size: 16, speed: 52 },
    { x: 1820, baseDelay: 40, size: 20, speed: 58 },
    { x: 1960, baseDelay: 18, size: 25, speed: 42 },
    { x: 1870, baseDelay: 50, size: 14, speed: 65 },
  ];

  const smokePositions = [
    { x: 1820, delay: 0 },
    { x: 1870, delay: 30 },
    { x: 1920, delay: 15 },
    { x: 1850, delay: 45 },
  ];

  const volcanoY = interpolate(volcanoProgress, [0, 1], [400, 0]);
  const volcanoOpacity = volcanoProgress;

  return (
    <AbsoluteFill
      style={{
        fontFamily: "'Inter', sans-serif",
        overflow: "hidden",
      }}
    >
      {/* Sky Background */}
      <AbsoluteFill>
        <div
          style={{
            width: "100%",
            height: "100%",
            background: `radial-gradient(ellipse at 50% 30%, #3d1a5c 0%, #1a0a2e 40%, #0a0010 100%)`,
            opacity: skyProgress,
          }}
        />
      </AbsoluteFill>

      {/* Stars */}
      {[...Array(40)].map((_, i) => {
        const starX = ((i * 97 + 31) % 3800) + 20;
        const starY = ((i * 131 + 57) % 1200) + 20;
        const starSize = ((i * 17) % 6) + 2;
        const twinkle = Math.sin(frame * 0.1 + i * 0.8) * 0.4 + 0.6;
        return (
          <div
            key={i}
            style={{
              position: "absolute",
              left: starX,
              top: starY,
              width: starSize,
              height: starSize,
              borderRadius: "50%",
              backgroundColor: "white",
              opacity: skyProgress * twinkle * 0.8,
            }}
          />
        );
      })}

      {/* Lava glow on horizon */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: "50%",
            transform: "translateX(-50%)",
            width: 1800,
            height: 600,
            background: `radial-gradient(ellipse at 50% 100%, rgba(255,69,0,${0.3 + glowPulse * 0.2}) 0%, rgba(255,140,0,0.1) 50%, transparent 80%)`,
            opacity: volcanoProgress,
          }}
        />
      </AbsoluteFill>

      {/* === VOLCANO === */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            bottom: 0,
            left: "50%",
            transform: `translateX(-50%) translateY(${volcanoY}px)`,
            opacity: volcanoOpacity,
            width: 2200,
          }}
        >
          <svg
            width="2200"
            height="1400"
            viewBox="0 0 2200 1400"
            style={{ display: "block" }}
          >
            {/* Far background mountains */}
            <path
              d="M0,1400 L0,900 Q200,700 400,800 Q600,700 800,600 Q1000,500 1100,550 Q1200,500 1400,600 Q1600,700 1800,800 Q2000,700 2200,900 L2200,1400 Z"
              fill="#1a0a1a"
              opacity="0.6"
            />

            {/* Main volcano body */}
            <path
              d={`M200,1400 Q400,1200 600,1000 Q750,850 900,750 Q980,700 1020,650 Q1060,600 1100,400 Q1140,600 1180,650 Q1220,700 1300,750 Q1450,850 1600,1000 Q1800,1200 2000,1400 Z`}
              fill={COLORS.rock}
            />

            {/* Volcano ridge detail */}
            <path
              d={`M500,1400 Q650,1100 800,900 Q950,780 1040,680 Q1075,640 1100,480 Q1125,640 1160,680 Q1250,780 1400,900 Q1550,1100 1700,1400 Z`}
              fill={COLORS.rockMid}
            />

            {/* Dark lava streaks going down sides */}
            <path
              d="M1100,480 Q1090,550 1080,620 Q1060,700 1040,750 Q1010,700 1020,620 Q1060,560 1100,480 Z"
              fill={COLORS.lava}
              opacity={0.4 + glowPulse * 0.3}
            />
            <path
              d="M1100,480 Q1110,550 1120,620 Q1140,700 1160,750 Q1190,700 1180,620 Q1140,560 1100,480 Z"
              fill={COLORS.lava}
              opacity={0.3 + glowPulse * 0.3}
            />

            {/* Rocky ledge at top where man stands */}
            <path
              d="M980,460 Q1040,440 1100,438 Q1160,440 1220,460 Q1200,490 1100,495 Q1000,490 980,460 Z"
              fill={COLORS.rockMid}
            />
            {/* Ledge edge highlight */}
            <path
              d="M985,465 Q1040,450 1100,448 Q1160,450 1215,465"
              stroke="rgba(255,255,255,0.15)"
              strokeWidth="4"
              fill="none"
              strokeLinecap="round"
            />

            {/* Crater rim */}
            <ellipse
              cx="1100"
              cy="438"
              rx="120"
              ry="28"
              fill={COLORS.rockDark}
              stroke={COLORS.rockMid}
              strokeWidth="6"
            />

            {/* Inner crater glow */}
            <ellipse
              cx="1100"
              cy="450"
              rx="90"
              ry="22"
              fill={`rgba(255,69,0,${0.4 + glowPulse * 0.4})`}
            />
            <ellipse
              cx="1100"
              cy="452"
              rx="60"
              ry="15"
              fill={`rgba(255,215,0,${0.3 + glowPulse * 0.5})`}
            />

            {/* Rock texture details */}
            {[...Array(12)].map((_, i) => {
              const rx = 200 + (i * 167) % 1700;
              const ry = 700 + (i * 113) % 500;
              return (
                <path
                  key={i}
                  d={`M${rx},${ry} Q${rx + 40},${ry - 30} ${rx + 80},${ry} Q${rx + 40},${ry + 10} ${rx},${ry} Z`}
                  fill="rgba(0,0,0,0.2)"
                />
              );
            })}
          </svg>
        </div>
      </AbsoluteFill>

      {/* Lava particles from crater */}
      {erupting && (
        <AbsoluteFill>
          <div style={{ position: "absolute", bottom: 600, left: 0, width: "100%", height: 400 }}>
            {lavaParticles.map((p, i) => (
              <LavaParticle key={i} {...p} />
            ))}
          </div>
        </AbsoluteFill>
      )}

      {/* Smoke puffs */}
      {erupting && (
        <AbsoluteFill>
          <div style={{ position: "absolute", bottom: 600, left: 0, width: "100%", height: 600 }}>
            {smokePositions.map((s, i) => (
              <SmokePuff key={i} {...s} />
            ))}
          </div>
        </AbsoluteFill>
      )}

      {/* === MAN + RING on volcano top === */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            bottom: 615,
            left: "50%",
            transform: `translateX(-50%) translateX(${shimmer}px)`,
            width: 400,
            height: 600,
          }}
        >
          {/* Ring above man */}
          <TheRing
            progress={ringProgress}
            hoverAmt={ringY}
            glowPulse={inscriptionGlow}
          />

          {/* Man */}
          <TheMan
            progress={manProgress}
            armRaise={armRaise}
            legSwing={legSwing}
            breathe={breathe}
          />
        </div>
      </AbsoluteFill>

      {/* Dramatic orange glow around the ring holder */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            bottom: 560,
            left: "50%",
            transform: "translateX(-50%)",
            width: 600,
            height: 600,
            background: `radial-gradient(ellipse at 50% 70%, rgba(255,215,0,${0.06 + inscriptionGlow * 0.08}) 0%, transparent 70%)`,
            pointerEvents: "none",
          }}
        />
      </AbsoluteFill>

      {/* Title text */}
      <AbsoluteFill>
        <div
          style={{
            position: "absolute",
            top: 120,
            left: 0,
            right: 0,
            display: "flex",
            flexDirection: "column",
            alignItems: "center",
            gap: 20,
          }}
        >
          <div
            style={{
              opacity: interpolate(ringProgress, [0, 1], [0, 1]),
              transform: `translateY(${interpolate(ringProgress, [0, 1], [-40, 0])}px)`,
              fontSize: 72,
              fontWeight: 800,
              color: COLORS.ringGold,
              letterSpacing: "0.12em",
              textShadow: `0 0 40px rgba(255,215,0,0.6), 0 0 80px rgba(255,215,0,0.3)`,
              textTransform: "uppercase",
            }}
          >
            One Ring to Rule Them All
          </div>
          <div
            style={{
              opacity: interpolate(armRaiseProgress, [0, 1], [0, 1]),
              transform: `translateY(${interpolate(armRaiseProgress, [0, 1], [20, 0])}px)`,
              fontSize: 36,
              fontWeight: 500,
              color: "rgba(255,200,200,0.7)",
              letterSpacing: "0.2em",
              textShadow: `0 0 20px rgba(255,100,100,0.4)`,
              textTransform: "uppercase",
            }}
          >
            Mount Doom
          </div>
        </div>
      </AbsoluteFill>

      {/* Vignette overlay */}
      <AbsoluteFill style={{ pointerEvents: "none" }}>
        <div
          style={{
            width: "100%",
            height: "100%",
            background:
              "radial-gradient(ellipse at 50% 50%, transparent 50%, rgba(0,0,0,0.5) 100%)",
          }}
        />
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      {/* Opening black */}
      <TransitionSeries.Sequence durationInFrames={20}>
        <BlackScreen />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: 20 })}
      />

      {/* Main scene */}
      <TransitionSeries.Sequence durationInFrames={175 + TRANSITION}>
        <VolcanoScene />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      {/* Closing black */}
      <TransitionSeries.Sequence durationInFrames={25}>
        <BlackScreen />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
